80"}, {"seed_key": "demo:question:aptitude_and_reasoning:quantitative_aptitude:8", "question_text": "A can finish a job in 5 days. What fraction of the job is done in 2 days?", "options": ["2/5", "1/5", "3/5", "4/5"], "correct_answer": 0, "difficulty": "hard", "explanation": "Daily rate is 1/5 of the job"}, {"seed_key": "demo:question:aptitude_and_reasoning:quantitative_aptitude:9", "question_text": "What is the compound interest on 1000 at 10% for 1 year?", "options": ["90", "110", "100", "121"], "correct_answer": 2, "difficulty": "hard", "explanation": "For one year, compound interest equals simple interest"}, {"seed_key": "demo:question:aptitude_and_reasoning:quantitative_aptitude:10", "question_text": "A mixture has 3 litres of water and 2 litres of juice. What fraction is juice?", "options": ["1/5", "2/5", "3/5", "2/3"], "correct_answer": 1, "difficulty": "hard", "explanation": "Juice is 2 litres out of a total of 5"}]}, {"name": "Logical Reasoning", "slug": "logical_reasoning", "questions": [{"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:1", "question_text": "All squares are rectangles. Which conclusion is definitely true?", "options": ["All squares are rectangles", "All rectangles are squares", "Some squares are triangles", "No square is a rectangle"], "correct_answer": 0, "difficulty": "easy", "explanation": "The conclusion repeats the given universal statement"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:2", "question_text": "Some cats are black. Which conclusion is valid?", "options": ["All cats are black", "Some black things are cats", "No black thing is a cat", "Every black thing is a cat"], "correct_answer": 1, "difficulty": "easy", "explanation": "If some cats are black, then some black things must be cats"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:3", "question_text": "Which number is the odd one out: 2, 4, 6, 9?", "options": ["2", "4", "9", "6"], "correct_answer": 2, "difficulty": "easy", "explanation": "The others are even numbers"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:4", "question_text": "A person facing north turns right. Which direction does the person face now?", "options": ["West", "South", "North", "East"], "correct_answer": 3, "difficulty": "medium", "explanation": "A right turn from north points east"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:5", "question_text": "All roses are flowers. Which conclusion is definitely true?", "options": ["Every flower is a rose", "Every rose is a flower", "No rose is a flower", "Some flowers are not flowers"], "correct_answer": 1, "difficulty": "medium", "explanation": "It restates the original premise"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:6", "question_text": "What comes next in the sequence A, C, E, G?", "options": ["H", "J", "I", "K"], "correct_answer": 2, "difficulty": "medium", "explanation": "The letters advance by skipping one each time"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:7", "question_text": "If today is Monday, what day will it be after 10 days?", "options": ["Wednesday", "Friday", "Saturday", "Thursday"], "correct_answer": 3, "difficulty": "medium", "explanation": "Ten days after Monday is three days ahead in the weekly cycle"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:8", "question_text": "If CAT is coded as DBU by shifting each letter by one, how is DOG coded?", "options": ["EPH", "DNG", "EOH", "FPH"], "correct_answer": 0, "difficulty": "hard", "explanation": "Shift D to E, O to P, and G to H"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:9", "question_text": "What is your mother's brother to you?", "options": ["Cousin", "Nephew", "Uncle", "Grandfather"], "correct_answer": 2, "difficulty": "hard", "explanation": "Your mother's brother is your uncle"}, {"seed_key": "demo:question:aptitude_and_reasoning:logical_reasoning:10", "question_text": "If all bloops are razzies and all razzies are lazzies, what follows?", "options": ["All lazzies are bloops", "All bloops are lazzies", "No bloops are lazzies", "Some lazzies are not razzies only"], "correct_answer": 1, "difficulty": "hard", "explanation": "The relationship is transitive"}]}, {"name": "Verbal Reasoning", "slug": "verbal_reasoning", "questions": [{"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:1", "question_text": "Book is to read as music is to what?", "options": ["Listen", "Write", "Paint", "Dance"], "correct_answer": 0, "difficulty": "easy", "explanation": "Books are read and music is listened to"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:2", "question_text": "Which word is a synonym of concise?", "options": ["Noisy", "Brief", "Costly", "Timid"], "correct_answer": 1, "difficulty": "easy", "explanation": "Concise means brief and to the point"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:3", "question_text": "Which word is an antonym of expand?", "options": ["Stretch", "Grow", "Contract", "Broaden"], "correct_answer": 2, "difficulty": "easy", "explanation": "Contract is the opposite of expand"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:4", "question_text": "Choose the word that best completes the sentence: The evidence was ___ to convict the suspect.", "options": ["Abundant", "Clear", "Final", "Insufficient"], "correct_answer": 3, "difficulty": "medium", "explanation": "The sentence requires a word meaning not enough"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:5", "question_text": "Rearrange the letters LPAEP to form a meaningful word.", "options": ["PAPER", "APPLE", "LAPSE", "PLEAT"], "correct_answer": 1, "difficulty": "medium", "explanation": "The letters can be reordered to spell APPLE"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:6", "question_text": "What is the one-word term for fear of heights?", "options": ["Claustrophobia", "Hydrophobia", "Acrophobia", "Arachnophobia"], "correct_answer": 2, "difficulty": "medium", "explanation": "Acrophobia means fear of heights"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:7", "question_text": "All finalists submitted the project. Mira is a finalist. What follows?", "options": ["Mira wrote every project", "No finalist submitted the project", "Mira is not a finalist", "Mira submitted the project"], "correct_answer": 3, "difficulty": "medium", "explanation": "Apply the general statement to Mira"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:8", "question_text": "Choose the correct passive form of: The team completed the task.", "options": ["The task was completed by the team", "The task completed the team", "The team was completed by the task", "The task has completing the team"], "correct_answer": 0, "difficulty": "hard", "explanation": "The object becomes the subject in passive voice"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:9", "question_text": "Doctor is to hospital as teacher is to what?", "options": ["Library", "Garden", "School", "Airport"], "correct_answer": 2, "difficulty": "hard", "explanation": "A teacher commonly works in a school"}, {"seed_key": "demo:question:aptitude_and_reasoning:verbal_reasoning:10", "question_text": "Finger is to hand as toe is to what?", "options": ["Leg", "Foot", "Ankle", "Knee"], "correct_answer": 1, "difficulty": "hard", "explanation": "A toe is part of a foot"}]}, {"name": "Data Interpretation", "slug": "data_interpretation", "questions": [{"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:1", "question_text": "A store sold 120 units in Q1 and 150 units in Q2. What was the increase?", "options": ["25%", "20%", "22.5%", "30%"], "correct_answer": 0, "difficulty": "easy", "explanation": "Increase is 30 on a base of 120"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:2", "question_text": "A shop earned 200, 250, and 300 over three days. What was the total earning?", "options": ["700", "750", "800", "850"], "correct_answer": 1, "difficulty": "easy", "explanation": "Add the three daily earnings"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:3", "question_text": "If 36 out of 60 students passed, how many failed?", "options": ["20", "22", "24", "26"], "correct_answer": 2, "difficulty": "easy", "explanation": "Failed students equal total minus passed"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:4", "question_text": "If a class has 18 boys and 12 girls, what is the ratio of boys to girls?", "options": ["2:3", "3:1", "4:3", "3:2"], "correct_answer": 3, "difficulty": "medium", "explanation": "Simplify 18:12 by dividing by 6"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:5", "question_text": "A bus starts empty, 50 passengers board, and 15 leave. How many remain?", "options": ["30", "35", "40", "45"], "correct_answer": 1, "difficulty": "medium", "explanation": "Subtract those who left from those who boarded"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:6", "question_text": "A library has 200 books and 40% are fiction. How many fiction books are there?", "options": ["60", "70", "80", "90"], "correct_answer": 2, "difficulty": "medium", "explanation": "Forty percent of 200 is 80"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:7", "question_text": "The temperatures for three days are 28, 30, and 32 degrees. What is the average?", "options": ["29", "31", "32", "30"], "correct_answer": 3, "difficulty": "medium", "explanation": "Average = (28 + 30 + 32) / 3"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:8", "question_text": "Revenue is 5000 and cost is 3500. What is the profit?", "options": ["1500", "1200", "1400", "1600"], "correct_answer": 0, "difficulty": "hard", "explanation": "Profit equals revenue minus cost"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:9", "question_text": "A population grows from 80,000 to 92,000. What is the percentage growth?", "options": ["10%", "12%", "15%", "20%"], "correct_answer": 2, "difficulty": "hard", "explanation": "Growth is 12,000 on a base of 80,000"}, {"seed_key": "demo:question:aptitude_and_reasoning:data_interpretation:10", "question_text": "Scores in five matches are 12, 18, 15, 25, and 20. What is the highest score?", "options": ["18", "25", "20", "22"], "correct_answer": 1, "difficulty": "hard", "explanation": "Identify the maximum value in the set"}]}, {"name": "Number Series", "slug": "number_series", "questions": [{"seed_key": "demo:question:aptitude_and_reasoning:number_series:1", "question_text": "What comes next in the series 2, 4, 6, 8?", "options": ["10", "9", "11", "12"], "correct_answer": 0, "difficulty": "easy", "explanation": "The pattern adds 2 each time"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:2", "question_text": "What comes next in the series 3, 6, 12, 24?", "options": ["30", "48", "36", "42"], "correct_answer": 1, "difficulty": "easy", "explanation": "The pattern doubles each term"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:3", "question_text": "What comes next in the series 1, 1, 2, 3, 5?", "options": ["6", "7", "8", "9"], "correct_answer": 2, "difficulty": "easy", "explanation": "Each term is the sum of the previous two"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:4", "question_text": "What comes next in the series 5, 10, 17, 26?", "options": ["35", "38", "39", "37"], "correct_answer": 3, "difficulty": "medium", "explanation": "The differences are 5, 7, 9, so next is 11"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:5", "question_text": "What comes next in the series 81, 27, 9, 3?", "options": ["0", "1", "2", "9"], "correct_answer": 1, "difficulty": "medium", "explanation": "Each term is divided by 3"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:6", "question_text": "What comes next in the series 2, 5, 10, 17?", "options": ["24", "25", "26", "27"], "correct_answer": 2, "difficulty": "medium", "explanation": "These are n^2 + 1 for n = 1, 2, 3, 4, 5"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:7", "question_text": "What comes next in the series 7, 14, 28, 56?", "options": ["96", "104", "120", "112"], "correct_answer": 3, "difficulty": "medium", "explanation": "The pattern doubles each term"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:8", "question_text": "What comes next in the series 100, 95, 85, 70?", "options": ["50", "55", "60", "65"], "correct_answer": 0, "difficulty": "hard", "explanation": "Subtract 5, then 10, then 15, then 20"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:9", "question_text": "What comes next in the series 1, 4, 9, 16?", "options": ["20", "24", "25", "26"], "correct_answer": 2, "difficulty": "hard", "explanation": "These are perfect squares"}, {"seed_key": "demo:question:aptitude_and_reasoning:number_series:10", "question_text": "What comes next in the series 2, 3, 5, 8, 13?", "options": ["18", "21", "20", "22"], "correct_answer": 1, "difficulty": "hard", "explanation": "Each term equals the sum of the previous two"}]}]}, {"name": "English", "slug": "english", "exam_title": "English - Comprehensive Test", "exam_description": "A 50-question demo paper on grammar, vocabulary, reading, correction, and word meaning.", "topics": [{"name": "Grammar", "slug": "grammar", "questions": [{"seed_key": "demo:question:english:grammar:1", "question_text": "In the sentence She sings, which word is the pronoun?", "options": ["She", "sings", "the", "sentence"], "correct_answer": 0, "difficulty": "easy", "explanation": "She replaces a noun and functions as a pronoun"}, {"seed_key": "demo:question:english:grammar:2", "question_text": "What is the past tense of go?", "options": ["goed", "went", "gone", "going"], "correct_answer": 1, "difficulty": "easy", "explanation": "Went is the correct simple past form"}, {"seed_key": "demo:question:english:grammar:3", "question_text": "Which part of speech usually modifies a noun?", "options": ["Adverb", "Verb", "Adjective", "Preposition"], "correct_answer": 2, "difficulty": "easy", "explanation": "Adjectives describe nouns"}, {"seed_key": "demo:question:english:grammar:4", "question_text": "Choose the correct sentence: He ___ to school every day.", "options": ["go", "gone", "going", "goes"], "correct_answer": 3, "difficulty": "medium", "explanation": "A third-person singular subject takes goes"}, {"seed_key": "demo:question:english:grammar:5", "question_text": "What is the plural form of child?", "options": ["childs", "children", "childes", "childrens"], "correct_answer": 1, "difficulty": "medium", "explanation": "Children is the irregular plural"}, {"seed_key": "demo:question:english:grammar:6", "question_text": "Which article is correct before honest?", "options": ["a", "the", "an", "no article"], "correct_answer": 2, "difficulty": "medium", "explanation": "Honest begins with a vowel sound"}, {"seed_key": "demo:question:english:grammar:7", "question_text": "Choose the correct sentence.", "options": ["The list of items are on the desk", "The list of items be on the desk", "The list of items were on the desk", "The list of items is on the desk"], "correct_answer": 3, "difficulty": "medium", "explanation": "The subject list is singular"}, {"seed_key": "demo:question:english:grammar:8", "question_text": "Choose the correct passive form of They built a bridge.", "options": ["A bridge was built by them", "A bridge is built by them", "They were built by a bridge", "A bridge built them"], "correct_answer": 0, "difficulty": "hard", "explanation": "Passive voice uses was built"}, {"seed_key": "demo:question:english:grammar:9", "question_text": "Complete the sentence: If I ___ time, I would travel.", "options": ["have", "has", "had", "having"], "correct_answer": 2, "difficulty": "hard", "explanation": "The second conditional uses if + past tense"}, {"seed_key": "demo:question:english:grammar:10", "question_text": "Identify the adverb in the sentence She spoke softly.", "options": ["She", "softly", "spoke", "sentence"], "correct_answer": 1, "difficulty": "hard", "explanation": "Softly modifies the verb spoke"}]}, {"name": "Vocabulary", "slug": "vocabulary", "questions": [{"seed_key": "demo:question:english:vocabulary:1", "question_text": "What does benevolent mean?", "options": ["Kind and generous", "Angry and violent", "Silent and shy", "Lazy and careless"], "correct_answer": 0, "difficulty": "easy", "explanation": "Benevolent describes someone kind and well-meaning"}, {"seed_key": "demo:question:english:vocabulary:2", "question_text": "Choose a synonym of rapid.", "options": ["Heavy", "Fast", "Calm", "Late"], "correct_answer": 1, "difficulty": "easy", "explanation": "Rapid means fast"}, {"seed_key": "demo:question:english:vocabulary:3", "question_text": "Choose an antonym of scarce.", "options": ["Rare", "Limited", "Abundant", "Insufficient"], "correct_answer": 2, "difficulty": "easy", "explanation": "Scarce means not enough, so abundant is the opposite"}, {"seed_key": "demo:question:english:vocabulary:4", "question_text": "What does diligent mean?", "options": ["Careless", "Noisy", "Forgetful", "Hardworking"], "correct_answer": 3, "difficulty": "medium", "explanation": "Diligent describes steady effort and hard work"}, {"seed_key": "demo:question:english:vocabulary:5", "question_text": "What does obsolete mean?", "options": ["Flexible", "Outdated", "Bright", "Valuable"], "correct_answer": 1, "difficulty": "medium", "explanation": "Obsolete means no longer in common use"}, {"seed_key": "demo:question:english:vocabulary:6", "question_text": "What does fragile mean?", "options": ["Very heavy", "Highly polished", "Easily broken", "Always useful"], "correct_answer": 2, "difficulty": "medium", "explanation": "Fragile items break easily"}, {"seed_key": "demo:question:english:vocabulary:7", "question_text": "What does vivid mean?", "options": ["Extremely dull", "Slightly hidden", "Randomly arranged", "Very clear and bright"], "correct_answer": 3, "difficulty": "medium", "explanation": "Vivid language produces strong clear images"}, {"seed_key": "demo:question:english:vocabulary:8", "question_text": "What does mitigate mean?", "options": ["Make less severe", "Increase sharply", "Ignore completely", "Measure exactly"], "correct_answer": 0, "difficulty": "hard", "explanation": "Mitigate means reduce intensity or seriousness"}, {"seed_key": "demo:question:english:vocabulary:9", "question_text": "What does ambiguous mean?", "options": ["Very short", "Completely honest", "Having more than one possible meaning", "Easy to count"], "correct_answer": 2, "difficulty": "hard", "explanation": "Ambiguous language can be interpreted in multiple ways"}, {"seed_key": "demo:question:english:vocabulary:10", "question_text": "What does resilient mean?", "options": ["Unable to move", "Able to recover quickly", "Easy to offend", "Slow to learn"], "correct_answer": 1, "difficulty": "hard", "explanation": "Resilient people or systems bounce back after difficulty"}]}, {"name": "Reading Comprehension", "slug": "reading_comprehension", "questions": [{"seed_key": "demo:question:english:reading_comprehension:1", "question_text": "Passage: Riya studied in short daily sessions instead of one long session. Over a month, her recall improved and her stress decreased. What is the main idea?", "options": ["Consistent short study improved learning", "Long sessions always fail", "Stress is useful for memory", "Riya stopped studying"], "correct_answer": 0, "difficulty": "easy", "explanation": "The passage highlights the benefit of regular shorter study sessions"}, {"seed_key": "demo:question:english:reading_comprehension:2", "question_text": "In the same passage, what improved over the month?", "options": ["Travel time", "Recall", "Attendance", "Classroom size"], "correct_answer": 1, "difficulty": "easy", "explanation": "The passage explicitly says her recall improved"}, {"seed_key": "demo:question:english:reading_comprehension:3", "question_text": "In the same passage, what happened to Riya's stress?", "options": ["It doubled", "It stayed exactly the same", "It decreased", "It became unimportant"], "correct_answer": 2, "difficulty": "easy", "explanation": "The passage says her stress decreased"}, {"seed_key": "demo:question:english:reading_comprehension:4", "question_text": "Which method did Riya avoid?", "options": ["Daily revision", "Writing notes", "Taking practice tests", "One long study session"], "correct_answer": 3, "difficulty": "medium", "explanation": "She chose short daily sessions instead of one long session"}, {"seed_key": "demo:question:english:reading_comprehension:5", "question_text": "What can be inferred from the passage?", "options": ["She studied only once", "Consistency supported her progress", "She stopped revising", "She changed schools"], "correct_answer": 1, "difficulty": "medium", "explanation": "Improved recall and lower stress suggest the regular method helped"}, {"seed_key": "demo:question:english:reading_comprehension:6", "question_text": "Passage: The city library introduced weekend workshops on coding and robotics. Attendance doubled within three months, especially among high school students. What topics were introduced?", "options": ["Music and dance", "History and law", "Coding and robotics", "Painting and drama"], "correct_answer": 2, "difficulty": "medium", "explanation": "The passage names coding and robotics directly"}, {"seed_key": "demo:question:english:reading_comprehension:7", "question_text": "What happened to workshop attendance?", "options": ["It halved", "It ended", "It stayed unchanged", "It doubled"], "correct_answer": 3, "difficulty": "medium", "explanation": "The passage states that attendance doubled"}, {"seed_key": "demo:question:english:reading_comprehension:8", "question_text": "Within how much time did attendance double?", "options": ["Three months", "Three weeks", "Six months", "One year"], "correct_answer": 0, "difficulty": "hard", "explanation": "The timeframe is given directly in the passage"}, {"seed_key": "demo:question:english:reading_comprehension:9", "question_text": "Which group showed special interest?", "options": ["Retired librarians", "Primary teachers only", "High school students", "Tourists"], "correct_answer": 2, "difficulty": "hard", "explanation": "The passage says especially among high school students"}, {"seed_key": "demo:question:english:reading_comprehension:10", "question_text": "What is the best inference from the second passage?", "options": ["Libraries should close on weekends", "Interest in practical tech learning increased", "Only robots matter now", "Attendance always falls after workshops"], "correct_answer": 1, "difficulty": "hard", "explanation": "The attendance growth suggests demand for applied tech learning"}]}, {"name": "Sentence Correction", "slug": "sentence_correction", "questions": [{"seed_key": "demo:question:english:sentence_correction:1", "question_text": "Choose the correct form: Neither of the boys ___ late.", "options": ["is", "are", "were", "be"], "correct_answer": 0, "difficulty": "easy", "explanation": "Neither is treated as singular here"}, {"seed_key": "demo:question:english:sentence_correction:2", "question_text": "Choose the correct form: She ___ like coffee.", "options": ["don't", "doesn't", "isn't", "won't"], "correct_answer": 1, "difficulty": "easy", "explanation": "Third-person singular takes does not"}, {"seed_key": "demo:question:english:sentence_correction:3", "question_text": "Choose the correct form: Each of the players ___ ready.", "options": ["were", "are", "was", "have"], "correct_answer": 2, "difficulty": "easy", "explanation": "Each is singular"}, {"seed_key": "demo:question:english:sentence_correction:4", "question_text": "Choose the correct sentence.", "options": ["I have less books than you", "I have lesser books than you", "I has fewer books than you", "I have fewer books than you"], "correct_answer": 3, "difficulty": "medium", "explanation": "Countable nouns take fewer rather than less"}, {"seed_key": "demo:question:english:sentence_correction:5", "question_text": "Choose the correct phrase.", "options": ["He is senior than me", "He is senior to me", "He is more senior than me only", "He is senior from me"], "correct_answer": 1, "difficulty": "medium", "explanation": "Senior takes the preposition to"}, {"seed_key": "demo:question:english:sentence_correction:6", "question_text": "Choose the correct sentence.", "options": ["The news are surprising", "The news be surprising", "The news is surprising", "The news were surprise"], "correct_answer": 2, "difficulty": "medium", "explanation": "News takes a singular verb"}, {"seed_key": "demo:question:english:sentence_correction:7", "question_text": "Choose the correct sentence.", "options": ["One of the student have won", "One of the students have won", "One of the student has woned", "One of the students has won"], "correct_answer": 3, "difficulty": "medium", "explanation": "The subject one is singular"}, {"seed_key": "demo:question:english:sentence_correction:8", "question_text": "Choose the correct form: If I ___ you, I would apologize.", "options": ["were", "was", "am", "be"], "correct_answer": 0, "difficulty": "hard", "explanation": "Formal subjunctive uses were"}, {"seed_key": "demo:question:english:sentence_correction:9", "question_text": "Choose the correct preposition: She is good ___ mathematics.", "options": ["in", "on", "at", "for"], "correct_answer": 2, "difficulty": "hard", "explanation": "Good at is the standard expression"}, {"seed_key": "demo:question:english:sentence_correction:10", "question_text": "Choose the correct pair: No sooner did he arrive ___ it started raining.", "options": ["when", "than", "then", "and"], "correct_answer": 1, "difficulty": "hard", "explanation": "The fixed expression is no sooner...than"}]}, {"name": "Synonyms and Antonyms", "slug": "synonyms_and_antonyms", "questions": [{"seed_key": "demo:question:english:synonyms_and_antonyms:1", "question_text": "Choose a synonym of honest.", "options": ["Truthful", "Cruel", "Slow", "Dim"], "correct_answer": 0, "difficulty": "easy", "explanation": "Truthful is close in meaning to honest"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:2", "question_text": "Choose an antonym of expand.", "options": ["Grow", "Contract", "Stretch", "Multiply"], "correct_answer": 1, "difficulty": "easy", "explanation": "Contract is the opposite of expand"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:3", "question_text": "Choose a synonym of ancient.", "options": ["Modern", "Tiny", "Old", "Sharp"], "correct_answer": 2, "difficulty": "easy", "explanation": "Ancient means very old"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:4", "question_text": "Choose an antonym of victory.", "options": ["Success", "Reward", "Effort", "Defeat"], "correct_answer": 3, "difficulty": "medium", "explanation": "Defeat is the opposite of victory"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:5", "question_text": "Choose a synonym of assist.", "options": ["Delay", "Help", "Hide", "Argue"], "correct_answer": 1, "difficulty": "medium", "explanation": "Assist means help"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:6", "question_text": "Choose an antonym of minor.", "options": ["Small", "Fewer", "Major", "Brief"], "correct_answer": 2, "difficulty": "medium", "explanation": "Major is the opposite of minor"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:7", "question_text": "Choose a synonym of silent.", "options": ["Bright", "Rough", "Sudden", "Quiet"], "correct_answer": 3, "difficulty": "medium", "explanation": "Quiet closely matches silent"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:8", "question_text": "Choose an antonym of generous.", "options": ["Stingy", "Helpful", "Open", "Cheerful"], "correct_answer": 0, "difficulty": "hard", "explanation": "Stingy is the opposite of generous"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:9", "question_text": "Choose a synonym of commence.", "options": ["Finish", "Delay", "Begin", "Avoid"], "correct_answer": 2, "difficulty": "hard", "explanation": "Commence means begin"}, {"seed_key": "demo:question:english:synonyms_and_antonyms:10", "question_text": "Choose an antonym of fragile.", "options": ["Thin", "Sturdy", "Tiny", "Dusty"], "correct_answer": 1, "difficulty": "hard", "explanation": "Sturdy means strong and not easily broken"}]}]}]$seed$::jsonb;
  v_subject jsonb;
  v_topic jsonb;
  v_question jsonb;
  v_subject_id uuid;
  v_topic_id uuid;
  v_exam_id uuid;
  v_question_id uuid;
  v_question_ids uuid[];
  v_legacy_exam_id uuid;
  v_subject_slug text;
  v_exam_title text;
  v_exam_description text;
begin
  select id into v_legacy_exam_id
  from public.exams
  where title = 'Algebra Fundamentals - Demo'
  limit 1;

  if v_legacy_exam_id is not null then
    begin
      delete from public.exam_questions where exam_id = v_legacy_exam_id;
      delete from public.questions where exam_id = v_legacy_exam_id;
      delete from public.exams where id = v_legacy_exam_id;
    exception when foreign_key_violation then
      update public.questions
      set is_active = false, updated_at = now()
      where exam_id = v_legacy_exam_id;

      update public.exams
      set status = 'archived',
          is_published = false,
          is_active = false,
          updated_at = now()
      where id = v_legacy_exam_id;
    end;
  end if;

  for v_subject in select value from jsonb_array_elements(v_seed)
  loop
    v_subject_slug := v_subject ->> 'slug';
    v_exam_title := v_subject ->> 'exam_title';
    v_exam_description := v_subject ->> 'exam_description';

    insert into public.subjects(name, is_active)
    values (v_subject ->> 'name', true)
    on conflict (name) do update
    set is_active = excluded.is_active,
        updated_at = now()
    returning id into v_subject_id;

    insert into public.exams(
      seed_key,
      title,
      description,
      subject_id,
      duration_minutes,
      total_marks,
      passing_marks,
      negative_marking,
      start_date,
      end_date,
      status,
      shuffle_questions,
      shuffle_options,
      allow_review,
      proctoring_enabled,
      webcam_required,
      camera_denied_action,
      fullscreen_required,
      max_tab_switches,
      attempt_limit,
      instructions,
      is_active,
      is_published
    )
    values (
      'demo:exam:' || v_subject_slug,
      v_exam_title,
      v_exam_description,
      v_subject_id,
      60,
      50,
      20,
      false,
      null,
      null,
      'published',
      true,
      true,
      true,
      false,
      false,
      'warn',
      false,
      3,
      3,
      'Demo comprehensive exam seeded from Supabase SQL content.',
      true,
      true
    )
    on conflict (seed_key) do update
    set title = excluded.title,
        description = excluded.description,
        subject_id = excluded.subject_id,
        duration_minutes = excluded.duration_minutes,
        total_marks = excluded.total_marks,
        passing_marks = excluded.passing_marks,
        negative_marking = excluded.negative_marking,
        start_date = excluded.start_date,
        end_date = excluded.end_date,
        status = excluded.status,
        shuffle_questions = excluded.shuffle_questions,
        shuffle_options = excluded.shuffle_options,
        allow_review = excluded.allow_review,
        proctoring_enabled = excluded.proctoring_enabled,
        webcam_required = excluded.webcam_required,
        camera_denied_action = excluded.camera_denied_action,
        fullscreen_required = excluded.fullscreen_required,
        max_tab_switches = excluded.max_tab_switches,
        attempt_limit = excluded.attempt_limit,
        instructions = excluded.instructions,
        is_active = excluded.is_active,
        is_published = excluded.is_published,
        updated_at = now()
    returning id into v_exam_id;

    v_question_ids := array[]::uuid[];

    for v_topic in select value from jsonb_array_elements(v_subject -> 'topics')
    loop
      insert into public.topics(subject_id, name, is_active)
      values (v_subject_id, v_topic ->> 'name', true)
      on conflict (subject_id, name) do update
      set is_active = excluded.is_active,
          updated_at = now()
      returning id into v_topic_id;

      for v_question in select value from jsonb_array_elements(v_topic -> 'questions')
      loop
        insert into public.questions(
          seed_key,
          exam_id,
          subject_id,
          topic_id,
          question_text,
          options,
          correct_answer,
          difficulty,
          marks,
          negative_marks,
          display_order,
          explanation,
          is_active
        )
        values (
          v_question ->> 'seed_key',
          v_exam_id,
          v_subject_id,
          v_topic_id,
          v_question ->> 'question_text',
          v_question -> 'options',
          (v_question ->> 'correct_answer')::integer,
          (v_question ->> 'difficulty')::public.question_difficulty,
          1,
          0,
          ((regexp_match(v_question ->> 'seed_key', ':(\d+)$'))[1])::integer +
            ((select count(*) from jsonb_array_elements(v_subject -> 'topics') with ordinality t(topic_value, ord)
               where topic_value ->> 'slug' < v_topic ->> 'slug') * 10),
          v_question ->> 'explanation',
          true
        )
        on conflict (seed_key) do update
        set exam_id = excluded.exam_id,
            subject_id = excluded.subject_id,
            topic_id = excluded.topic_id,
            question_text = excluded.question_text,
            options = excluded.options,
            correct_answer = excluded.correct_answer,
            difficulty = excluded.difficulty,
            marks = excluded.marks,
            negative_marks = excluded.negative_marks,
            display_order = excluded.display_order,
            explanation = excluded.explanation,
            is_active = excluded.is_active,
            updated_at = now()
        returning id into v_question_id;

        v_question_ids := array_append(v_question_ids, v_question_id);
      end loop;
    end loop;

    delete from public.exam_questions where exam_id = v_exam_id;

    insert into public.exam_questions(exam_id, question_id, display_order)
    select v_exam_id, question_id, display_order
    from unnest(v_question_ids) with ordinality as seeded(question_id, display_order);

    update public.questions
    set is_active = false,
        updated_at = now()
    where seed_key like ('demo:question:' || v_subject_slug || ':%')
      and id <> all(v_question_ids);
  end loop;
end $$;

commit;
